-- Preserve every extra hall as an administrative annex, rather than deleting purchased buildings.
with ranked as (select id,row_number() over(partition by city_id order by case when placement_state='placed' then 0 else 1 end,placed_at,id) n from public.nexus_city_placements where building_code='CITY_HALL_3B'), converted as (
 update public.nexus_city_placements p set building_code='CITIZEN_SERVICES_3B' from ranked r where p.id=r.id and r.n>1 returning p.*)
insert into public.nexus_city_journal(city_id,user_id,action,reference_id,coins,metadata)
select p.city_id,c.user_id,'hall_to_annex',p.id,0,'{"preserved":true,"reason":"one_city_hall"}'::jsonb from converted p join public.nexus_cities c using(city_id);
create unique index city3b_one_hall_per_city on public.nexus_city_placements(city_id) where building_code='CITY_HALL_3B';
create function public.city3b_building_limit_guard() returns trigger language plpgsql security invoker set search_path='' as $$
declare maximum integer;
begin
 select greatest(0,least(50,coalesce((metadata->>'max_per_city')::integer,0))) into maximum from public.nexus_city_buildings where code=new.building_code;
 if maximum>0 then
  perform 1 from public.nexus_cities where city_id=new.city_id for update;
  if (select count(*) from public.nexus_city_placements where city_id=new.city_id and building_code=new.building_code and id<>new.id)>=maximum then
   if new.building_code='CITY_HALL_3B' then raise exception 'Ta ville possède déjà sa mairie. Déplace-la ou replace-la depuis la réserve.';end if;
   raise exception 'Limite de % bâtiment(s) par ville',maximum;
  end if;
 end if;
 return new;
end $$;
revoke all on function public.city3b_building_limit_guard() from public,anon,authenticated;
grant execute on function public.city3b_building_limit_guard() to service_role;
create trigger city3b_building_limit before insert or update of building_code,city_id on public.nexus_city_placements for each row execute function public.city3b_building_limit_guard();
create or replace function public.nexus_city_life_metrics(p_user uuid,p_population integer,p_policy text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare c public.nexus_cities; m jsonb; capacity integer:=0; jobs integer:=0; connected integer:=0; total integer:=0;
 water integer:=0; energy integer:=0; health integer:=0; education integer:=0; food integer:=0; green integer:=0; culture integer:=0; transit integer:=0; maintenance integer:=0; safety integer:=0; fire integer:=0; cleanliness integer:=0; internet integer:=0; justice integer:=0; sport integer:=0;
 b record; role text; half numeric; px numeric; pz numeric; close_road boolean; working integer; employed integer; mobility integer; happiness integer; needs jsonb:='[]'::jsonb; n record; score integer; demand integer;
begin
 select * into c from public.nexus_cities where user_id=p_user;
 if not found then raise exception 'Ville introuvable'; end if;
 m:=public.nexus_city_campaign_metrics(p_user); half:=50+greatest(1,c.land_tier)*45;
 for b in select p.*,d.category,d.metadata from public.nexus_city_placements p join public.nexus_city_buildings d on d.code=p.building_code
  where p.city_id=c.city_id and coalesce(p.placement_state,'placed')='placed' and (p.construction_ready_at is null or p.construction_ready_at<=now()) loop
  role:=coalesce(b.metadata->>'city_role',case b.category when 'home' then 'housing' when 'shop' then 'commerce' when 'community' then 'civic' when 'nature' then 'green' when 'culture' then 'mixed' when 'monument' then 'landmark' else 'decoration' end);
  total:=total+1; px:=b.x+coalesce(b.footprint_w,1)/2.0;pz:=b.z+coalesce(b.footprint_h,1)/2.0;
  close_road:=false;
  if not close_road then
   select exists(select 1 from jsonb_array_elements(case when jsonb_typeof(c.city->'roads')='array' then c.city->'roads' else '[]'::jsonb end) r where public.nexus_city_life_road_distance(px,pz,r)<=14) into close_road;
  end if;
  if close_road then connected:=connected+1; end if;
  capacity:=capacity+case role when 'housing' then 18 else 0 end;
  jobs:=jobs+greatest(0,least(1000,coalesce((b.metadata->>'jobs')::integer,case role when 'commerce' then 12 when 'civic' then 6 when 'mobility' then 6 when 'mixed' then 8 else 0 end)));
  water:=water+case when b.metadata->>'service'='water' then greatest(0,least(1000,coalesce((b.metadata->>'service_capacity')::integer,60))) else 0 end;
  energy:=energy+case when b.metadata->>'service'='energy' then greatest(0,least(1000,coalesce((b.metadata->>'service_capacity')::integer,60))) else 0 end;
  health:=health+case when b.metadata->>'service'='health' then greatest(0,least(1000,coalesce((b.metadata->>'service_capacity')::integer,40))) else 0 end;
  education:=education+case when b.metadata->>'service'='education' then greatest(0,least(1000,coalesce((b.metadata->>'service_capacity')::integer,30))) else 0 end;
  food:=food+case when role='commerce' then 40 else 0 end;
  green:=green+case when role='green' then 24 else 0 end;
  culture:=culture+case when b.category='culture' then 30 else 0 end;
  transit:=transit+case when role='mobility' and close_road then 1 else 0 end;
  safety:=safety+case when b.metadata->>'service'='safety' and close_road then coalesce((b.metadata->>'service_capacity')::integer,60) else 0 end;
  fire:=fire+case when b.metadata->>'service'='fire' and close_road then coalesce((b.metadata->>'service_capacity')::integer,60) else 0 end;
  cleanliness:=cleanliness+case when b.metadata->>'service'='cleanliness' and close_road then coalesce((b.metadata->>'service_capacity')::integer,60) else 0 end;
  internet:=internet+case when b.metadata->>'service'='internet' and close_road then coalesce((b.metadata->>'service_capacity')::integer,60) else 0 end;
  justice:=justice+case when b.metadata->>'service'='justice' and close_road then coalesce((b.metadata->>'service_capacity')::integer,60) else 0 end;
  maintenance:=maintenance+case when b.metadata->>'service'='roads' and close_road then 1 else 0 end;
  sport:=sport+case when b.category='sport' and close_road then coalesce((b.metadata->>'service_capacity')::integer,40) else 0 end;
 end loop;
 working:=ceil(greatest(0,p_population)*.6); employed:=least(working,jobs);
 mobility:=case when total=0 then 0 else least(100,round(connected::numeric/total*50)::integer+least(30,transit*15)+least(20,(m->>'roads')::integer*4)+least(10,maintenance*5)) end;
 for n in select * from (values ('water','Eau',water,1.0),('energy','Énergie',energy,1.0),('food','Commerces',food,1.0),('health','Soins',health,.6),('education','Éducation',education,.35),('green','Espaces verts',green,.8),('culture','Culture',culture,.5),('safety','Sécurité',safety,case when c.city_level>=3 then .6 else 0 end),('fire','Secours incendie',fire,case when c.city_level>=3 then .6 else 0 end),('cleanliness','Propreté',cleanliness,case when c.city_level>=3 then .6 else 0 end),('internet','Téléphone & Internet',internet,case when c.city_level>=4 then .8 else 0 end),('justice','Justice',justice,case when c.city_level>=6 then .3 else 0 end),('sport','Sports',sport,case when c.city_level>=4 then .5 else 0 end)) as v(code,label,capacity,factor) loop
  demand:=ceil(greatest(0,p_population)*n.factor);score:=case when demand=0 then 0 else least(100,round(n.capacity::numeric/demand*100)::integer) end;
  if p_policy='green' and n.code='green' and n.capacity>0 then score:=least(100,score+10);end if;
  if p_policy='culture' and n.code='culture' and n.capacity>0 then score:=least(100,score+10);end if;
  needs:=needs||jsonb_build_array(jsonb_build_object('code',n.code,'label',n.label,'score',score,'capacity',n.capacity,'demand',demand));
  m:=m||jsonb_build_object(n.code,case when n.code in ('culture','green') then coalesce((m->>n.code)::integer,0) else score end,n.code||'_score',score);
 end loop;
 select case when p_population=0 then 0 else least(100,round(25+coalesce(avg((r->>'score')::integer),0)*.55+mobility*.1+case when working=0 then 0 else employed::numeric/working*10 end+case when p_policy='balanced' then 5 else 0 end)::integer) end into happiness from jsonb_array_elements(needs) r where (r->>'demand')::integer>0;
 return m||jsonb_build_object('housingCapacity',capacity,'jobs',jobs,'workingPopulation',working,'employed',employed,'employment',case when working=0 then 0 else round(employed::numeric/working*100)::integer end,
  'population',greatest(0,p_population),'mobility',mobility,'connectedBuildings',connected,'placedBuildings',total,'happiness',happiness,'needs',needs);
end $$;

