 select '[{"code": "welcome", "title": "Bienvenue chez nous", "voice": "Lina", "description": "Accueille les premières familles et garde un commerce ouvert pendant deux cycles.", "cycles": 2, "coins": 120, "cityXp": 250, "requirements": [{"metric": "population", "target": 8, "label": "Habitants installés"}, {"metric": "commerce", "target": 1, "label": "Commerce placé"}], "action": {"tab": "build", "building": "SHOP_3B"}}, {"code": "green_walk", "title": "La promenade des voisins", "voice": "Sami", "description": "Prépare deux espaces verts et de vrais chemins pour notre première promenade.", "cycles": 2, "coins": 180, "cityXp": 350, "requirements": [{"metric": "population", "target": 12, "label": "Habitants installés"}, {"metric": "green", "target": 2, "label": "Espaces verts placés"}, {"metric": "roads", "target": 2, "label": "Axes personnels distincts"}], "action": {"tab": "build", "building": "TREE_MATRIX"}}, {"code": "market_day", "title": "Le marché du quartier", "voice": "Nora", "description": "Soutiens les commerçants avec eau, énergie et des habitants au rendez-vous.", "cycles": 3, "coins": 250, "cityXp": 500, "requirements": [{"metric": "population", "target": 20, "label": "Habitants installés"}, {"metric": "commerce", "target": 2, "label": "Commerces placés"}, {"metric": "water", "target": 60, "label": "Couverture de l’eau (%)"}, {"metric": "energy", "target": 60, "label": "Couverture de l’énergie (%)"}], "action": {"tab": "build", "building": "WATER_3B"}}, {"code": "school_days", "title": "La rentrée des quartiers", "voice": "Aïcha", "description": "Fais fonctionner ensemble l’école, les soins et les transports pendant trois cycles.", "cycles": 3, "coins": 300, "cityXp": 650, "requirements": [{"metric": "population", "target": 30, "label": "Habitants installés"}, {"metric": "education", "target": 60, "label": "Couverture de l’éducation (%)"}, {"metric": "health", "target": 60, "label": "Couverture des soins (%)"}, {"metric": "mobility", "target": 45, "label": "Mobilité (%)"}], "action": {"tab": "build", "building": "SCHOOL_3B"}}, {"code": "makers", "title": "Les ateliers ouverts", "voice": "Élio", "description": "Ouvre la transmission et le travail aux habitants de ta cité.", "cycles": 4, "coins": 400, "cityXp": 850, "requirements": [{"metric": "population", "target": 45, "label": "Habitants installés"}, {"metric": "culture", "target": 2, "label": "Lieux culturels placés"}, {"metric": "employment", "target": 65, "label": "Actifs avec un emploi (%)"}], "action": {"tab": "build", "building": "WORKSHOP_3B"}}, {"code": "transit_week", "title": "Une ville qui se relie", "voice": "Inès", "description": "Maintiens un réseau de transport et cinq axes pour faciliter le quotidien.", "cycles": 4, "coins": 500, "cityXp": 1100, "requirements": [{"metric": "population", "target": 60, "label": "Habitants installés"}, {"metric": "mobility", "target": 65, "label": "Mobilité (%)"}, {"metric": "roads", "target": 5, "label": "Axes personnels distincts"}], "action": {"tab": "build", "tool": "road"}}, {"code": "neighbourhood_festival", "title": "Le festival des habitants", "voice": "Maël", "description": "Réunis culture, sport et espaces verts ; conserve une ville agréable pendant cinq cycles.", "cycles": 5, "coins": 650, "cityXp": 1400, "requirements": [{"metric": "population", "target": 80, "label": "Habitants installés"}, {"metric": "culture", "target": 3, "label": "Lieux culturels placés"}, {"metric": "sport", "target": 1, "label": "Lieu sportif placé"}, {"metric": "happiness", "target": 65, "label": "Bien-être (%)"}], "action": {"tab": "build", "building": "ARENA_1618"}}, {"code": "eight_heritages", "title": "La fête des huit héritages", "voice": "Conseil des quartiers", "description": "Rassemble les huit quartiers dans une ville qui prend soin de ses habitants.", "cycles": 6, "coins": 800, "cityXp": 1800, "requirements": [{"metric": "population", "target": 100, "label": "Habitants installés"}, {"metric": "districts", "target": 8, "label": "Quartiers ouverts"}, {"metric": "happiness", "target": 70, "label": "Bien-être (%)"}, {"metric": "employment", "target": 75, "label": "Actifs avec un emploi (%)"}], "action": {"tab": "districts"}}, {"code": "safe_city", "title": "Une ville qui protège", "voice": "Conseil municipal", "description": "Fais fonctionner les services municipaux et maintiens leur couverture pendant quatre cycles.", "cycles": 4, "coins": 500, "cityXp": 1200, "requirements": [{"metric": "population", "target": 80, "label": "Habitants"}, {"metric": "safety", "target": 70, "label": "Sécurité (%)"}, {"metric": "fire", "target": 70, "label": "Secours (%)"}, {"metric": "cleanliness", "target": 70, "label": "Propreté (%)"}], "action": {"tab": "build", "building": "FIRE_STATION_3B"}}, {"code": "digital_city", "title": "Les quartiers connectés", "voice": "Conseil municipal", "description": "Fais fonctionner les services municipaux et maintiens leur couverture pendant quatre cycles.", "cycles": 4, "coins": 500, "cityXp": 1200, "requirements": [{"metric": "population", "target": 100, "label": "Habitants"}, {"metric": "internet", "target": 75, "label": "Connexion (%)"}, {"metric": "employment", "target": 75, "label": "Emploi (%)"}], "action": {"tab": "build", "building": "TELECOM_3B"}}, {"code": "civic_city", "title": "Le maire et ses habitants", "voice": "Conseil municipal", "description": "Fais fonctionner les services municipaux et maintiens leur couverture pendant quatre cycles.", "cycles": 4, "coins": 500, "cityXp": 1200, "requirements": [{"metric": "population", "target": 120, "label": "Habitants"}, {"metric": "justice", "target": 70, "label": "Justice (%)"}, {"metric": "sport_score", "target": 65, "label": "Sports (%)"}], "action": {"tab": "build", "building": "COURTHOUSE_3B"}}]'::jsonb;
